using Microsoft::WRL::ComPtr;
class Failure:public std::runtime_error {
 static std::string Message(const char* operation,HRESULT result){std::ostringstream text;text<<operation<<" failed (HRESULT 0x"<<std::hex<<std::setw(8)<<std::setfill('0')<<static_cast<uint32_t>(result)<<").";return text.str();}
public:Failure(const char* operation,HRESULT result):std::runtime_error(Message(operation,result)){}
};
void Check(HRESULT result,const char* operation){if(FAILED(result))throw Failure(operation,result);}
uint32_t Aligned(uint32_t value){return (value+15u)&~15u;}
ComPtr<IMFMediaType> Type(REFGUID subtype,uint32_t w,uint32_t h,uint32_t fps){ComPtr<IMFMediaType> type;Check(MFCreateMediaType(&type),"Create video media type");Check(type->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Video),"Set video type");Check(type->SetGUID(MF_MT_SUBTYPE,subtype),"Set video subtype");Check(MFSetAttributeSize(type.Get(),MF_MT_FRAME_SIZE,w,h),"Set video size");Check(MFSetAttributeRatio(type.Get(),MF_MT_FRAME_RATE,fps,1),"Set video rate");Check(MFSetAttributeRatio(type.Get(),MF_MT_PIXEL_ASPECT_RATIO,1,1),"Set pixel ratio");Check(type->SetUINT32(MF_MT_INTERLACE_MODE,MFVideoInterlace_Progressive),"Set progressive video");return type;}
void Property(IMFTransform* transform,const GUID& key,uint32_t value,bool required=false){ComPtr<ICodecAPI> codec;auto result=transform->QueryInterface(IID_PPV_ARGS(&codec));if(SUCCEEDED(result)){VARIANT data;VariantInit(&data);data.vt=VT_UI4;data.ulVal=value;result=codec->SetValue(&key,&data);}if(required)Check(result,"Set bounded video decoder property");}
void Begin(IMFTransform* transform){Check(transform->ProcessMessage(MFT_MESSAGE_NOTIFY_BEGIN_STREAMING,0),"Begin decoder streaming");Check(transform->ProcessMessage(MFT_MESSAGE_NOTIFY_START_OF_STREAM,0),"Start decoder stream");}
struct Output {HRESULT status=S_OK;ComPtr<IMFSample> sample;};
Output Take(IMFTransform* transform){MFT_OUTPUT_STREAM_INFO info{};Check(transform->GetOutputStreamInfo(0,&info),"Read decoder buffer policy");Output out;
 if(!(info.dwFlags&(MFT_OUTPUT_STREAM_PROVIDES_SAMPLES|MFT_OUTPUT_STREAM_CAN_PROVIDE_SAMPLES))){if(!info.cbSize||info.cbSize>MaxWidth*Aligned(MaxHeight)*4u||info.cbAlignment>4096)throw std::runtime_error("Decoded buffer policy exceeds its bounds.");ComPtr<IMFMediaBuffer> buffer;Check(MFCreateAlignedMemoryBuffer(info.cbSize,info.cbAlignment?info.cbAlignment-1:0,&buffer),"Allocate bounded output buffer");Check(MFCreateSample(&out.sample),"Create output sample");Check(out.sample->AddBuffer(buffer.Get()),"Attach output buffer");}
 MFT_OUTPUT_DATA_BUFFER data{};data.pSample=out.sample.Get();DWORD status=0;out.status=transform->ProcessOutput(0,1,&data,&status);if(data.pEvents)data.pEvents->Release();if(data.pSample!=out.sample.Get())out.sample.Attach(data.pSample);if((status&MFT_PROCESS_OUTPUT_STATUS_NEW_STREAMS)&&out.status!=MF_E_TRANSFORM_STREAM_CHANGE)throw std::runtime_error("Dynamic decoder streams are unsupported.");return out;}
ComPtr<IMFSample> Sample(const uint8_t* bytes,size_t count,LONGLONG time,LONGLONG duration,bool keyFrame){ComPtr<IMFMediaBuffer> buffer;Check(MFCreateMemoryBuffer(static_cast<DWORD>(count),&buffer),"Allocate H.264 input");BYTE* output=nullptr;Check(buffer->Lock(&output,nullptr,nullptr),"Lock H.264 input");std::memcpy(output,bytes,count);Check(buffer->Unlock(),"Unlock H.264 input");Check(buffer->SetCurrentLength(static_cast<DWORD>(count)),"Set H.264 input size");ComPtr<IMFSample> sample;Check(MFCreateSample(&sample),"Create H.264 sample");Check(sample->AddBuffer(buffer.Get()),"Attach H.264 sample");Check(sample->SetSampleTime(time),"Set H.264 sample time");Check(sample->SetSampleDuration(duration),"Set H.264 sample duration");if(keyFrame)Check(sample->SetUINT32(MFSampleExtension_CleanPoint,TRUE),"Set key frame flag");return sample;}
void ValidateAnnexB(const uint8_t* bytes,size_t count){if(!bytes||count<5||count>MaxFrameBytes)throw std::invalid_argument("H.264 access unit must contain 5 bytes to 4 MiB.");size_t at=0;unsigned units=0;
 while(at<count){size_t zeros=0;while(at<count&&!bytes[at]){++zeros;++at;}if(zeros<2||at==count||bytes[at++]!=1||at==count||++units>1024)throw std::invalid_argument("Invalid bounded H.264 Annex-B access unit.");const auto nal=bytes[at];if((nal&0x80)||(nal&31)==0||(nal&31)>=24)throw std::invalid_argument("Unsupported H.264 NAL type.");++at;while(at+2<count&&!(bytes[at]==0&&bytes[at+1]==0&&(bytes[at+2]==1||(at+3<count&&bytes[at+2]==0&&bytes[at+3]==1))))++at;if(at+2>=count)return;
 }
}
